import { Router } from 'express';
import { z } from 'zod';
import type { LibraryRouteServices } from './types';
import type {
  NavigationAcknowledgementResponse,
  ViewNavigationsResponse,
} from '../../types/api-responses';

const TargetSchema = z
  .object({
    requestId: z.string().min(1),
    projectId: z.string().optional(),
    sessionId: z.string().optional(),
    variantId: z.string().optional(),
  })
  .refine(
    (target) =>
      Boolean(target.sessionId) === Boolean(target.variantId) &&
      (!target.sessionId || Boolean(target.projectId)),
    'An exact direction needs a project, session, and variant',
  );

export const createNavigationRoutes = ({
  library,
  navigation,
  track,
}: LibraryRouteServices): Router => {
  const router = Router();
  router.post('/navigations', track('navigation'), async (req, res) => {
    const request = TargetSchema.parse(req.body);
    await library.assertNavigationTarget(request);
    res.json(await navigation.request(request));
  });
  router.put('/views/:viewId', (req, res) => {
    const body = z.object({ isFocused: z.boolean() }).parse(req.body);
    navigation.connect({ viewId: req.params.viewId, ...body });
    res.json({
      navigations: navigation.pending(req.params.viewId),
    } satisfies ViewNavigationsResponse);
  });
  router.post('/views/:viewId/acknowledgements', (req, res) => {
    const { sequence } = z
      .object({ sequence: z.number().int().positive() })
      .parse(req.body);
    res.json({
      acknowledged: navigation.acknowledge(req.params.viewId, sequence),
    } satisfies NavigationAcknowledgementResponse);
  });
  return router;
};
